import requests
import json

headers = {
    'User-Agent': 'Mozilla/5.0 (ResearchBot; institution@example.com)'
}

# Try SEC XBRL company facts
try:
    url = 'https://data.sec.gov/api/xbrl/companyfacts/CIK0001045810.json'
    r = requests.get(url, headers=headers, timeout=15)
    print('Status:', r.status_code)
    if r.status_code == 200:
        facts = r.json()
        print('Facts keys:', list(facts['facts'].keys())[:30])

        # Look for common stock shares outstanding
        for key in facts['facts'].keys():
            if 'stock' in key.lower() or 'share' in key.lower() or 'equity' in key.lower() or 'common' in key.lower():
                print('\nFact:', key)
                units = facts['facts'][key].get('units', {})
                for ukey, uvals in units.items():
                    print(f'  Units: {ukey}')
                    for v in uvals[:5]:
                        print(f'    {v}')
except Exception as e:
    print('Error:', e)
